CREATE SCHEMA IF NOT EXISTS analytics;
COMMENT ON SCHEMA analytics IS 'Privacy-aware product events, funnels, cohorts and controlled experiments';

CREATE TABLE analytics.event_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),name varchar(80) NOT NULL,version smallint NOT NULL CHECK(version>0),description varchar(500) NOT NULL,property_schema jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(property_schema)='object'),purpose text NOT NULL CHECK(purpose IN('functional','analytics')),state text NOT NULL DEFAULT'published'CHECK(state IN('draft','published','retired')),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,name,version));
CREATE INDEX analytics_event_definition_idx ON analytics.event_definitions(tenant_id,state,name,version DESC);

CREATE TABLE analytics.events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),event_name varchar(80) NOT NULL,event_version smallint NOT NULL CHECK(event_version>0),idempotency_key varchar(160) NOT NULL,session_id uuid NOT NULL,subject_id uuid,anonymous_id varchar(160),properties jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(properties)='object'),consent text NOT NULL CHECK(consent IN('none','functional','analytics')),occurred_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(subject_id IS NOT NULL OR anonymous_id IS NOT NULL),UNIQUE(tenant_id,idempotency_key));
CREATE INDEX analytics_event_range_idx ON analytics.events(tenant_id,event_name,occurred_at DESC);
CREATE INDEX analytics_event_subject_idx ON analytics.events(tenant_id,subject_id,occurred_at DESC)WHERE subject_id IS NOT NULL;
CREATE INDEX analytics_event_session_idx ON analytics.events(tenant_id,session_id,occurred_at);

CREATE TABLE analytics.identity_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),anonymous_id varchar(160) NOT NULL,subject_id uuid NOT NULL,linked_at timestamptz NOT NULL DEFAULT clock_timestamp(),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,anonymous_id));
CREATE INDEX analytics_identity_subject_idx ON analytics.identity_links(tenant_id,subject_id,linked_at DESC);

CREATE TABLE analytics.funnel_definitions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),key varchar(80) NOT NULL,name varchar(120) NOT NULL,version integer NOT NULL DEFAULT 1 CHECK(version>0),steps jsonb NOT NULL CHECK(jsonb_typeof(steps)='array'AND jsonb_array_length(steps)BETWEEN 2 AND 12),conversion_window_hours integer NOT NULL CHECK(conversion_window_hours BETWEEN 1 AND 720),state text NOT NULL DEFAULT'draft'CHECK(state IN('draft','published','retired')),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,key,version));
CREATE INDEX analytics_funnel_definition_idx ON analytics.funnel_definitions(tenant_id,state,key,version DESC);

CREATE TABLE analytics.funnel_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),funnel_id uuid NOT NULL REFERENCES analytics.funnel_definitions(id)ON DELETE RESTRICT,bucket_date date NOT NULL,dimensions jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(dimensions)='object'),step_counts jsonb NOT NULL CHECK(jsonb_typeof(step_counts)='array'),conversion_bps integer NOT NULL CHECK(conversion_bps BETWEEN 0 AND 10000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,funnel_id,bucket_date,dimensions));
CREATE INDEX analytics_funnel_snapshot_idx ON analytics.funnel_snapshots(tenant_id,funnel_id,bucket_date DESC);

CREATE TABLE analytics.cohort_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),cohort_key varchar(80) NOT NULL DEFAULT'first_active_week',cohort_date date NOT NULL,period_number smallint NOT NULL CHECK(period_number BETWEEN 0 AND 52),cohort_size integer NOT NULL CHECK(cohort_size>=0),retained_users integer NOT NULL CHECK(retained_users>=0 AND retained_users<=cohort_size),retention_bps integer NOT NULL CHECK(retention_bps BETWEEN 0 AND 10000),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,cohort_key,cohort_date,period_number));
CREATE INDEX analytics_cohort_lookup_idx ON analytics.cohort_snapshots(tenant_id,cohort_key,cohort_date DESC,period_number);

CREATE TABLE analytics.experiments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),key varchar(80) NOT NULL,name varchar(120) NOT NULL,hypothesis varchar(500) NOT NULL,state text NOT NULL DEFAULT'draft'CHECK(state IN('draft','scheduled','running','paused','completed','cancelled')),primary_metric varchar(80) NOT NULL,guardrail_metrics jsonb NOT NULL DEFAULT'[]'CHECK(jsonb_typeof(guardrail_metrics)='array'),minimum_sample integer NOT NULL CHECK(minimum_sample>=100),starts_at timestamptz,ends_at timestamptz,created_by uuid NOT NULL,approved_by uuid,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(approved_by IS NULL OR approved_by<>created_by),CHECK(ends_at IS NULL OR starts_at IS NULL OR ends_at>starts_at),UNIQUE(tenant_id,key));
CREATE INDEX analytics_experiment_state_idx ON analytics.experiments(tenant_id,state,starts_at);

CREATE TABLE analytics.experiment_variants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),experiment_id uuid NOT NULL REFERENCES analytics.experiments(id)ON DELETE RESTRICT,key varchar(40) NOT NULL,name varchar(80) NOT NULL,weight_bps integer NOT NULL CHECK(weight_bps BETWEEN 1 AND 9999),configuration jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(configuration)='object'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(experiment_id,key));
CREATE INDEX analytics_variant_experiment_idx ON analytics.experiment_variants(tenant_id,experiment_id);

CREATE TABLE analytics.experiment_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),experiment_id uuid NOT NULL REFERENCES analytics.experiments(id)ON DELETE RESTRICT,variant_id uuid NOT NULL REFERENCES analytics.experiment_variants(id)ON DELETE RESTRICT,subject_key_hash char(64) NOT NULL CHECK(subject_key_hash~'^[a-f0-9]{64}$'),assigned_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,experiment_id,subject_key_hash));
CREATE INDEX analytics_assignment_variant_idx ON analytics.experiment_assignments(tenant_id,experiment_id,variant_id,assigned_at);

CREATE TABLE analytics.experiment_exposures(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),experiment_id uuid NOT NULL REFERENCES analytics.experiments(id)ON DELETE RESTRICT,variant_id uuid NOT NULL REFERENCES analytics.experiment_variants(id)ON DELETE RESTRICT,assignment_id uuid NOT NULL REFERENCES analytics.experiment_assignments(id)ON DELETE RESTRICT,idempotency_key varchar(160) NOT NULL,session_id uuid NOT NULL,exposed_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,idempotency_key));
CREATE INDEX analytics_exposure_range_idx ON analytics.experiment_exposures(tenant_id,experiment_id,variant_id,exposed_at DESC);

CREATE TABLE analytics.experiment_metric_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),experiment_id uuid NOT NULL REFERENCES analytics.experiments(id)ON DELETE RESTRICT,variant_id uuid NOT NULL REFERENCES analytics.experiment_variants(id)ON DELETE RESTRICT,bucket_date date NOT NULL,sample_size integer NOT NULL CHECK(sample_size>=0),conversions integer NOT NULL CHECK(conversions>=0 AND conversions<=sample_size),rate_bps integer NOT NULL CHECK(rate_bps BETWEEN 0 AND 10000),guardrail_state text NOT NULL CHECK(guardrail_state IN('ok','warning','breached')),statistics jsonb NOT NULL DEFAULT '{}'CHECK(jsonb_typeof(statistics)='object'),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,experiment_id,variant_id,bucket_date));
CREATE INDEX analytics_experiment_metric_idx ON analytics.experiment_metric_snapshots(tenant_id,experiment_id,bucket_date DESC);

CREATE TABLE analytics.daily_metrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES platform.tenants(id),metric_date date NOT NULL,active_users integer NOT NULL DEFAULT 0 CHECK(active_users>=0),sessions integer NOT NULL DEFAULT 0 CHECK(sessions>=0),listing_views integer NOT NULL DEFAULT 0 CHECK(listing_views>=0),contacts integer NOT NULL DEFAULT 0 CHECK(contacts>=0),contact_rate_bps integer NOT NULL DEFAULT 0 CHECK(contact_rate_bps BETWEEN 0 AND 10000),retained_users integer NOT NULL DEFAULT 0 CHECK(retained_users>=0),revenue_irr bigint NOT NULL DEFAULT 0 CHECK(revenue_irr>=0),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(tenant_id,metric_date));
CREATE INDEX analytics_daily_metrics_idx ON analytics.daily_metrics(tenant_id,metric_date DESC);

CREATE FUNCTION analytics.reject_immutable_mutation()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION'analytics_evidence_append_only';END$$;
CREATE TRIGGER analytics_events_immutable BEFORE UPDATE OR DELETE ON analytics.events FOR EACH ROW EXECUTE FUNCTION analytics.reject_immutable_mutation();
CREATE TRIGGER analytics_assignments_immutable BEFORE UPDATE OR DELETE ON analytics.experiment_assignments FOR EACH ROW EXECUTE FUNCTION analytics.reject_immutable_mutation();
CREATE TRIGGER analytics_exposures_immutable BEFORE UPDATE OR DELETE ON analytics.experiment_exposures FOR EACH ROW EXECUTE FUNCTION analytics.reject_immutable_mutation();

DO $$DECLARE table_name text;BEGIN FOREACH table_name IN ARRAY ARRAY['event_definitions','events','identity_links','funnel_definitions','funnel_snapshots','cohort_snapshots','experiments','experiment_variants','experiment_assignments','experiment_exposures','experiment_metric_snapshots','daily_metrics']LOOP EXECUTE format('ALTER TABLE analytics.%I ENABLE ROW LEVEL SECURITY',table_name);EXECUTE format('ALTER TABLE analytics.%I FORCE ROW LEVEL SECURITY',table_name);EXECUTE format('CREATE POLICY %I ON analytics.%I USING(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)WITH CHECK(tenant_id=NULLIF(current_setting(''app.current_tenant_id'',true),'''')::uuid)',table_name||'_tenant_isolation',table_name);END LOOP;END$$;
